// Parse Meta Cloud API webhook payload
const body = $json.body || $json;
const entry = body.entry || [];

if (!entry.length) return { json: { skip: true } };

const changes = entry[0]?.changes || [];
if (!changes.length) return { json: { skip: true } };

const value = changes[0]?.value;
if (!value || !value.messages || !value.messages.length) {
  return { json: { skip: true } };
}

const msg = value.messages[0];
const contacts = value.contacts || [];
const contact = contacts.find(c => c.wa_id === msg.from) || {};
const metadata = value.metadata || {};

let messageBody = '';
switch (msg.type) {
  case 'text': messageBody = msg.text?.body || ''; break;
  case 'image': messageBody = msg.image?.caption || ''; break;
  case 'video': messageBody = msg.video?.caption || ''; break;
  case 'audio': messageBody = ''; break;
  case 'location': messageBody = '📍 Lokasi: ' + (msg.location?.latitude || '') + ', ' + (msg.location?.longitude || ''); break;
  case 'document': messageBody = msg.document?.caption || msg.document?.filename || ''; break;
  default: messageBody = '(' + msg.type + ')';
}

return {
  json: {
    skip: false,
    phoneNumberId: metadata.phone_number_id,
    from: msg.from,
    messageId: msg.id,
    timestamp: msg.timestamp,
    type: msg.type,
    body: messageBody,
    contactName: contact.profile?.name || msg.from,
    sessionId: 'meta_' + metadata.phone_number_id
  }
};

const trigger = $('Parse Meta Payload').item.json;
const senderId = trigger.from || '';
const message = trigger.body || '';

if (!senderId) { throw new Error('Sender ID tidak ditemukan dari Meta webhook'); }

return {
  json: {
    mode: 'production',
    message: message,
    sessionId: senderId,
    chatId: senderId,
    platform: 'meta_cloud',
    phoneNumberId: trigger.phoneNumberId,
    metaSessionId: trigger.sessionId,
    contactName: trigger.contactName,
    agentConfig: null
  }
};

